"""
SenseVoice worker process — loads FunASR in a child so the parent can kill it on cancel.

CLI:
  python -m transub_engine.asr.sensevoice_worker --request req.json --output out.json
  python -m transub_engine.asr.sensevoice_worker --serve   # warm JSONL protocol on stdin

Progress: JSON lines on stdout (one object per line).
Result: writes ``{"ok": true, "cues": [...]}`` or ``{"ok": false, "error": "..."}``.

Serve mode keeps FunASR loaded across jobs until stdin closes or ``{"op":"shutdown"}``.
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Any


def _force_utf8_stdio() -> None:
    """Windows consoles default to the ANSI code page (e.g. GBK); progress JSON must be UTF-8."""
    for stream in (sys.stdout, sys.stderr):
        try:
            reconf = getattr(stream, "reconfigure", None)
            if callable(reconf):
                reconf(encoding="utf-8", errors="replace")
        except Exception:
            pass


_force_utf8_stdio()


def _emit(obj: dict[str, Any]) -> None:
    # Always write UTF-8 bytes so a parent that decodes UTF-8 never sees GBK mojibake
    # (Chinese Windows stdout often defaults to cp936 even when the parent requested utf-8).
    line = (json.dumps(obj, ensure_ascii=False) + "\n").encode("utf-8", errors="replace")
    buf = getattr(sys.stdout, "buffer", None)
    if buf is not None:
        buf.write(line)
        buf.flush()
    else:
        sys.stdout.write(line.decode("utf-8", errors="replace"))
        sys.stdout.flush()


def _run_one(req: dict[str, Any]) -> list[Any]:
    from .sensevoice import sensevoice_transcribe

    def on_progress(ev: dict[str, Any]) -> None:
        payload = dict(ev) if isinstance(ev, dict) else {"detail": str(ev)}
        payload.setdefault("type", "progress")
        _emit(payload)

    return sensevoice_transcribe(
        media_path=str(req.get("media_path") or ""),
        language=str(req.get("language") or "auto"),
        asr_model=str(req.get("asr_model") or "sensevoice-small"),
        vad_model=str(req.get("vad_model") or "fsmn-vad"),
        vad_options=req.get("vad_options") if isinstance(req.get("vad_options"), dict) else {},
        device=str(req.get("device") or "auto"),
        on_progress=on_progress,
        force_inprocess=True,
    )


def _handle_request_file(req_path: Path, out_path: Path) -> int:
    try:
        req = json.loads(req_path.read_text(encoding="utf-8"))
    except Exception as err:
        _emit({"type": "error", "message": f"bad request: {err}"})
        out_path.write_text(
            json.dumps({"ok": False, "error": str(err)}, ensure_ascii=False),
            encoding="utf-8",
        )
        return 2

    try:
        cues = _run_one(req if isinstance(req, dict) else {})
        out_path.write_text(
            json.dumps({"ok": True, "cues": cues}, ensure_ascii=False),
            encoding="utf-8",
        )
        _emit({"type": "done", "cueCount": len(cues or [])})
        return 0
    except Exception as err:
        import traceback

        tb = traceback.format_exc()
        _emit({"type": "error", "message": str(err)})
        try:
            out_path.write_text(
                json.dumps(
                    {"ok": False, "error": str(err), "traceback": tb},
                    ensure_ascii=False,
                ),
                encoding="utf-8",
            )
        except Exception:
            pass
        return 1


def _serve() -> int:
    """Warm worker: read JSONL commands from stdin until shutdown/EOF."""
    _emit({"type": "ready"})
    for raw in sys.stdin:
        line = (raw or "").strip()
        if not line:
            continue
        try:
            cmd = json.loads(line)
        except Exception as err:
            _emit({"type": "error", "message": f"bad command: {err}"})
            continue
        if not isinstance(cmd, dict):
            _emit({"type": "error", "message": "command must be an object"})
            continue
        op = str(cmd.get("op") or "").strip().lower()
        if op in ("shutdown", "exit", "quit"):
            _emit({"type": "shutdown"})
            return 0
        if op != "run":
            _emit({"type": "error", "message": f"unknown op: {op}"})
            continue
        req_path = Path(str(cmd.get("request") or ""))
        out_path = Path(str(cmd.get("output") or ""))
        marker = str(cmd.get("marker") or "").strip()
        if not req_path.is_file() or not out_path.parent.exists():
            _emit({"type": "error", "message": "missing request/output path"})
            if marker:
                try:
                    Path(marker).write_text("0", encoding="utf-8")
                except Exception:
                    pass
            continue
        rc = _handle_request_file(req_path, out_path)
        _emit(
            {
                "type": "job_done",
                "ok": rc == 0,
                "marker": marker or None,
            }
        )
        if marker:
            try:
                Path(marker).write_text("1" if rc == 0 else "0", encoding="utf-8")
            except Exception:
                pass
    return 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="sensevoice_worker")
    parser.add_argument("--request", default=None, help="JSON request path")
    parser.add_argument("--output", default=None, help="JSON result path")
    parser.add_argument(
        "--serve",
        action="store_true",
        help="Warm mode: JSONL commands on stdin (keeps FunASR loaded)",
    )
    args = parser.parse_args(argv)

    if args.serve:
        return _serve()

    if not args.request or not args.output:
        parser.error("--request and --output are required unless --serve")
    return _handle_request_file(Path(args.request), Path(args.output))


if __name__ == "__main__":
    raise SystemExit(main())
